// src/domain/key-rotator/QuotaManager.ts
class QuotaManager {
  supabase = null;
  exhaustedSet = new Set;
  buildKey(provider, model, apiKeyHash) {
    return `${provider}:${model}:${apiKeyHash}`;
  }
  getApiKeyHash(apiKey) {
    return apiKey.slice(-8);
  }
  getSupabase() {
    if (!this.supabase) {
      this.supabase = createClient(env3.supabaseUrl, env3.supabaseServiceRoleKey);
    }
    return this.supabase;
  }
  async initialize() {
    await this.loadExhaustedKeys();
  }
  async loadExhaustedKeys() {
    const now = new Date().toISOString();
    const { data, error } = await this.getSupabase().from("gateway_quota_exhausted").select("provider, model, api_key_hash").gt("reset_at", now);
    if (error) {
      console.error("[Gateway] Failed to load exhausted keys:", error);
      return;
    }
    this.exhaustedSet.clear();
    for (const row of data ?? []) {
      this.exhaustedSet.add(this.buildKey(row.provider, row.model, row.api_key_hash));
    }
    console.info(`[Gateway] Loaded ${this.exhaustedSet.size} exhausted keys from Supabase`);
    if (this.exhaustedSet.size > 0) {
      console.info(`[Gateway] Exhausted: ${Array.from(this.exhaustedSet).join(", ")}`);
    }
  }
  calcResetAt(provider) {
    const now = new Date;
    const tomorrow = new Date(now);
    tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
    if (provider === "gemini") {
      tomorrow.setUTCHours(env3.geminiResetHour, 0, 0, 0);
    } else if (provider === "cline") {
      tomorrow.setUTCHours(env3.clineResetHour, 0, 0, 0);
    } else if (provider === "kilo") {
      tomorrow.setUTCHours(env3.kiloResetHour, 0, 0, 0);
    } else if (provider === "openrouter") {
      tomorrow.setUTCHours(env3.openrouterResetHour, 0, 0, 0);
    } else {
      tomorrow.setUTCHours(0, 0, 0, 0);
    }
    return tomorrow;
  }
  async markExhausted(provider, model, apiKey) {
    const hash = this.getApiKeyHash(apiKey);
    const resetAt = this.calcResetAt(provider);
    this.exhaustedSet.add(this.buildKey(provider, model, hash));
    this.getSupabase().from("gateway_quota_exhausted").upsert({
      provider,
      model,
      api_key_hash: hash,
      exhausted_at: new Date().toISOString(),
      reset_at: resetAt.toISOString()
    }, {
      onConflict: "provider,model,api_key_hash"
    }).then((result) => {
      if (result.error)
        console.error("[Gateway] Failed to mark exhausted:", result.error);
    });
  }
  isExhaustedLocal(provider, model, apiKey) {
    const hash = this.getApiKeyHash(apiKey);
    return this.exhaustedSet.has(this.buildKey(provider, model, hash));
  }
  async isExhausted(provider, model, apiKey) {
    if (this.isExhaustedLocal(provider, model, apiKey))
      return true;
    const hash = this.getApiKeyHash(apiKey);
    const now = new Date().toISOString();
    const { data, error } = await this.getSupabase().from("gateway_quota_exhausted").select("id").eq("provider", provider).eq("model", model).eq("api_key_hash", hash).gt("reset_at", now).single();
    if (error)
      return false;
    return !!data;
  }
  async cleanupExpired() {
    const now = new Date().toISOString();
    const { error, count } = await this.getSupabase().from("gateway_quota_exhausted").delete().lt("reset_at", now);
    if (error) {
      console.error("[Gateway] Cleanup failed:", error);
      return 0;
    }
    await this.loadExhaustedKeys();
    return count ?? 0;
  }
  getExhaustedSet() {
    return this.exhaustedSet;
  }
}
var quotaManager = new QuotaManager;

// src/domain/types.ts
var FALLBACK_CHAIN = [
  {
    provider: "cline",
    modelId: "nvidia/nemotron-3-ultra-550b-a55b:free",
    displayName: "Cline/Nemotron"
  },
  { provider: "kilo", modelId: "kilo-auto/free", displayName: "Kilo/Auto" },
  { provider: "openrouter", modelId: "openrouter/free", displayName: "OpenRouter/Free" },
  { provider: "gemini", modelId: "gemini-3.5-flash-lite", displayName: "Gemini/3.5Lite" },
  { provider: "gemini", modelId: "gemini-3.1-flash-lite", displayName: "Gemini/3.1Lite" }
];

// src/domain/proxy/adapters/GeminiAdapter.ts
class GeminiAdapter {
  baseUrl;
  constructor(config) {
    this.baseUrl = config.baseUrl.replace("{model}", "");
  }
  async call(request, modelId, apiKey, timeoutMs = 60000) {
    const geminiRequest = this.transformRequest(request);
    const controller = new AbortController;
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const url = `${this.baseUrl}${modelId}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(geminiRequest),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      const responseText = await response.text();
      if (!response.ok) {
        return {
          ok: false,
          status: response.status,
          errorBody: responseText
        };
      }
      const rawData = JSON.parse(responseText);
      const chatResponse = this.transformResponse(rawData, modelId);
      return {
        ok: true,
        status: response.status,
        response: chatResponse,
        errorBody: ""
      };
    } catch (error) {
      clearTimeout(timeoutId);
      const message = error instanceof Error ? error.message : "Network error";
      const isTimeout = error instanceof Error && error.name === "AbortError";
      return {
        ok: false,
        status: isTimeout ? 408 : 0,
        errorBody: isTimeout ? `Timeout after ${timeoutMs}ms` : message
      };
    }
  }
  transformRequest(request) {
    const contents = [];
    for (const msg of request.messages) {
      if (msg.role === "system") {
        continue;
      }
      contents.push({
        role: msg.role === "assistant" ? "model" : "user",
        parts: [{ text: msg.content }]
      });
    }
    const systemMsg = request.messages.find((m) => m.role === "system");
    if (systemMsg && contents.length > 0 && contents[0].role === "user") {
      contents[0].parts[0].text = `${systemMsg.content}

${contents[0].parts[0].text}`;
    }
    return {
      contents,
      generationConfig: {
        temperature: request.temperature ?? 0.7,
        maxOutputTokens: request.max_tokens ?? 2000
      }
    };
  }
  transformResponse(raw, modelId) {
    const candidate = raw.candidates[0];
    const content = candidate?.content?.parts?.[0]?.text ?? "";
    const finishReason = this.mapFinishReason(candidate?.finishReason);
    const usage = raw.usageMetadata;
    return {
      id: `chatcmpl-gemini-${Date.now()}`,
      object: "chat.completion",
      model: modelId,
      choices: [
        {
          index: 0,
          message: {
            role: "assistant",
            content
          },
          finish_reason: finishReason
        }
      ],
      usage: {
        prompt_tokens: usage?.promptTokenCount ?? 0,
        completion_tokens: usage?.candidatesTokenCount ?? 0,
        total_tokens: usage?.totalTokenCount ?? 0
      }
    };
  }
  mapFinishReason(reason) {
    if (!reason)
      return "stop";
    const lower = reason.toLowerCase();
    if (lower.includes("max_token") || lower.includes("length"))
      return "length";
    if (lower.includes("safety") || lower.includes("filter"))
      return "content_filter";
    if (lower.includes("error") || lower.includes("fail"))
      return "error";
    return "stop";
  }
}

// src/domain/proxy/adapters/OpenAICompatAdapter.ts
class OpenAICompatAdapter {
  config;
  constructor(config) {
    this.config = config;
  }
  async call(request, modelId, apiKey, timeoutMs = 60000) {
    const headers = {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      ...this.config.defaultHeaders
    };
    const body = {
      model: modelId,
      messages: request.messages,
      temperature: request.temperature ?? 0.7,
      max_tokens: request.max_tokens ?? 2000,
      stream: request.stream ?? false
    };
    const controller = new AbortController;
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(this.config.baseUrl, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      const responseText = await response.text();
      if (!response.ok) {
        return {
          ok: false,
          status: response.status,
          errorBody: responseText
        };
      }
      const data = JSON.parse(responseText);
      return {
        ok: true,
        status: response.status,
        response: {
          ...data,
          model: modelId
        },
        errorBody: ""
      };
    } catch (error) {
      clearTimeout(timeoutId);
      const message = error instanceof Error ? error.message : "Network error";
      const isTimeout = error instanceof Error && error.name === "AbortError";
      return {
        ok: false,
        status: isTimeout ? 408 : 0,
        errorBody: isTimeout ? `Timeout after ${timeoutMs}ms` : message
      };
    }
  }
}

// src/domain/proxy/ProxyService.ts
class ProxyService {
  rotator;
  cooldown;
  classifier;
  quota;
  adapters;
  coldStartTried = new Set;
  constructor() {
    this.rotator = new KeyRotator([
      { provider: "cline", keys: env3.clineKeys },
      { provider: "kilo", keys: env3.kiloKeys },
      { provider: "openrouter", keys: env3.openrouterKeys },
      { provider: "gemini", keys: env3.geminiKeys }
    ]);
    this.cooldown = new CooldownManager;
    this.classifier = new ErrorClassifier;
    this.quota = new QuotaManager;
    this.adapters = new Map;
    this.initializeAdapters();
  }
  initializeAdapters() {
    this.adapters.set("cline", new OpenAICompatAdapter({
      baseUrl: "https://api.cline.bot/api/v1/chat/completions",
      apiKeys: env3.clineKeys
    }));
    this.adapters.set("kilo", new OpenAICompatAdapter({
      baseUrl: "https://api.kilo.ai/api/gateway/chat/completions",
      apiKeys: env3.kiloKeys
    }));
    this.adapters.set("openrouter", new OpenAICompatAdapter({
      baseUrl: "https://openrouter.ai/api/v1/chat/completions",
      apiKeys: env3.openrouterKeys,
      defaultHeaders: {
        "HTTP-Referer": "https://seedtick.app",
        "X-Title": "SeedTick"
      }
    }));
    this.adapters.set("gemini", new GeminiAdapter({
      baseUrl: "https://generativelanguage.googleapis.com/v1beta/models/",
      apiKeys: env3.geminiKeys,
      queryAuth: true
    }));
  }
  async initialize() {
    await this.quota.initialize();
  }
  async chat(request) {
    const attempts = [];
    console.info("[Gateway] Chat request received, starting fallback chain");
    for (const modelConfig of FALLBACK_CHAIN) {
      const { provider, modelId } = modelConfig;
      const keys = this.rotator.getKeysForProvider(provider);
      if (keys.length === 0) {
        console.info(`[Gateway] No keys for ${provider}, skipping`);
        continue;
      }
      console.info(`[Gateway] Trying provider=${provider} model=${modelId} keys=${keys.length}`);
      for (const apiKey of keys) {
        if (this.cooldown.isCoolingDown(provider, modelId, apiKey)) {
          console.info(`[Gateway] Skipping ${provider}:${modelId}:${apiKey.slice(-8)} (cooldown)`);
          continue;
        }
        if (this.quota.isExhaustedLocal(provider, modelId, apiKey)) {
          console.info(`[Gateway] Skipping ${provider}:${modelId}:${apiKey.slice(-8)} (daily exhausted)`);
          continue;
        }
        const adapter = this.adapters.get(provider);
        if (!adapter) {
          console.error(`[Gateway] No adapter for provider: ${provider}`);
          continue;
        }
        const result = await this.callWithColdStartRetry(adapter, request, modelId, apiKey, provider, attempts);
        if (result.ok && result.response) {
          console.info(`[Gateway] Success: ${provider}:${modelId}:${apiKey.slice(-8)}`);
          return result.response;
        }
        const category = this.classifier.classify(result.status, result.errorBody);
        console.warn(`[Gateway] Error: ${provider}:${modelId}:${apiKey.slice(-8)} status=${result.status} category=${category} body=${result.errorBody.slice(0, 100)}`);
        const attempt = {
          provider,
          modelId,
          apiKeyHash: apiKey.slice(-8),
          httpStatus: result.status,
          errorCategory: category,
          errorSnippet: result.errorBody.slice(0, 200),
          attemptedAt: new Date().toISOString()
        };
        attempts.push(attempt);
        await this.handleError(category, provider, modelId, apiKey, keys);
        if (this.shouldBreakModelLoop(category)) {
          break;
        }
      }
    }
    return {
      error: {
        code: "GATEWAY_ALL_EXHAUSTED",
        message: "\uBAA8\uB4E0 LLM \uC81C\uACF5\uC0AC\uC758 \uD0A4\uC640 \uBAA8\uB378\uC774 \uC18C\uC9C4\uB418\uC5C8\uC2B5\uB2C8\uB2E4",
        type: "gateway_error",
        attempts
      }
    };
  }
  async callWithColdStartRetry(adapter, request, modelId, apiKey, provider, attempts) {
    const coldStartKey = `${provider}:${modelId}`;
    const isFirstCall = !this.coldStartTried.has(coldStartKey);
    let result = await adapter.call(request, modelId, apiKey, 60000);
    const isTimeoutOrNetwork = result.status === 408 || result.status === 0;
    if (isFirstCall && isTimeoutOrNetwork) {
      console.info(`[Gateway] Cold start timeout/network error for ${provider}:${modelId}:${apiKey.slice(-8)}, retrying with 120s timeout...`);
      this.coldStartTried.add(coldStartKey);
      const retryAttempt = {
        provider,
        modelId,
        apiKeyHash: apiKey.slice(-8),
        httpStatus: result.status,
        errorCategory: "unknown",
        errorSnippet: `Cold start retry: ${result.errorBody}`,
        attemptedAt: new Date().toISOString()
      };
      attempts.push(retryAttempt);
      result = await adapter.call(request, modelId, apiKey, 120000);
      if (result.ok && result.response) {
        console.info(`[Gateway] Cold start retry success: ${provider}:${modelId}:${apiKey.slice(-8)}`);
        return result;
      }
      console.warn(`[Gateway] Cold start retry failed: ${provider}:${modelId}:${apiKey.slice(-8)} status=${result.status}`);
    }
    if (isFirstCall) {
      this.coldStartTried.add(coldStartKey);
    }
    return result;
  }
  async handleError(category, provider, modelId, apiKey, allKeys) {
    console.info(`[Gateway] Handling error: ${category} for ${provider}:${modelId}:${apiKey.slice(-8)}`);
    switch (category) {
      case "rpm_exceeded":
      case "tpm_exceeded":
        this.cooldown.setCooldown(provider, modelId, apiKey, 60000, category);
        console.info(`[Gateway] Set cooldown 60s for ${provider}:${modelId}:${apiKey.slice(-8)} (${category})`);
        break;
      case "daily_exhausted":
        this.quota.markExhausted(provider, modelId, apiKey);
        console.info(`[Gateway] Marked daily exhausted for ${provider}:${modelId}:${apiKey.slice(-8)}`);
        break;
      case "forbidden":
      case "unauthorized":
        this.cooldown.setCooldown(provider, modelId, apiKey, 3600000, category);
        console.info(`[Gateway] Set cooldown 1h for ${provider}:${modelId}:${apiKey.slice(-8)} (${category})`);
        break;
      case "model_not_found":
        this.cooldown.setModelCooldownAllKeys(provider, modelId, allKeys, 86400000, category);
        console.info(`[Gateway] Set cooldown 24h for ALL keys of ${provider}:${modelId} (${category})`);
        break;
      case "server_overloaded":
        this.cooldown.setCooldown(provider, modelId, apiKey, 30000, category);
        console.info(`[Gateway] Set cooldown 30s for ${provider}:${modelId}:${apiKey.slice(-8)} (${category})`);
        break;
      case "timeout":
      case "network_error":
        this.cooldown.setCooldown(provider, modelId, apiKey, 30000, category);
        console.info(`[Gateway] Set cooldown 30s for ${provider}:${modelId}:${apiKey.slice(-8)} (${category})`);
        break;
      default:
        console.info(`[Gateway] Breaking model loop for ${provider}:${modelId} (${category})`);
        break;
    }
  }
  shouldBreakModelLoop(category) {
    return [
      "model_not_found",
      "context_too_long",
      "output_too_long",
      "safety_filter",
      "unknown"
    ].includes(category);
  }
  getCooldownMap() {
    return this.cooldown.getMap();
  }
  getExhaustedKeys() {
    return this.quota.getExhaustedSet();
  }
}
var proxyService = new ProxyService;

